async function openGraph(page) {
  await page.addInitScript(() => {
    localStorage.setItem('token', 'motion-test-session')
    localStorage.setItem('userId', '7')
    localStorage.setItem('roleCode', 'student')
  })
  const graph = { graphId: 'motion', title: '机器学习概述', courseId: 1, chapterId: 2, status: 'PUBLISHED', revision: 1, graphVersion: 1, publishedVersion: 1, nodes: concepts, edges: relations, evidence: [], truncated: false }
  await page.route('**/*', async route => {
    const url = new URL(route.request().url())
    if (url.port === '5173' || !/^\/(api|courses)(\/|$)/.test(url.pathname)) return route.continue()
    const ok = data => route.fulfill({ json: { code: '200', data } })
    if (url.pathname === '/courses') return ok({ records: [{ id: 1, title: '人工智能基础' }] })
    if (url.pathname === '/api/rag/graphs') return ok([graph])
    if (url.pathname === '/api/rag/graphs/motion') return ok(graph)
    if (url.pathname.endsWith('/neighbors')) return ok({ nodes: [concepts[0], concepts[2]], edges: [{ ...relations[0], id: 'regression-task', target: 'regression' }], truncated: false })
    return ok([])
  })
  await page.goto('/chapter-knowledge-graph?courseId=1&graphId=motion')
  const stage = page.getByTestId('graph-stage')
  await expect(stage).toBeVisible()
  await stage.scrollIntoViewIfNeeded()
  await expect(stage).toHaveAttribute('data-layout-state', 'ready')
  return stage
}

async function pixels(page) {
  return page.getByTestId('graph-motion-layer').evaluate(canvas => {
    const pixels = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data
    let hash = 2166136261, painted = 0
    for (let index = 0; index < pixels.length; index += 4) {
      if (pixels[index + 3]) painted++
      hash = Math.imul(hash ^ pixels[index] ^ (pixels[index + 1] << 8) ^ (pixels[index + 2] << 16) ^ (pixels[index + 3] << 24), 16777619)
    }
    return { hash: hash >>> 0, painted }
  })
}

